import { REGIONS } from '../constants/regions';
import TravelOceanScene from '../three/TravelOceanScene';
import type { TravelState, Player } from '../types';
import { Button } from './ui';

interface TravelScreenProps {
  travelState: TravelState;
  player: Player;
  progress: number;
  onCancel: () => void;
}

export default function TravelScreen({ travelState, player, progress, onCancel }: TravelScreenProps) {
  const from = REGIONS[travelState.fromRegion];
  const to = REGIONS[travelState.toRegion];

  const elapsed = Date.now() - travelState.startTime;
  const remaining = Math.max(0, travelState.duration - elapsed);
  const remainingSeconds = Math.ceil(remaining / 1000);
  const minutes = Math.floor(remainingSeconds / 60);
  const seconds = remainingSeconds % 60;

  const encountersDone = travelState.encounters.filter(e => e.resolved).length;
  const totalEncounters = travelState.encounters.length;

  return (
    <div className="w-full h-full relative overflow-hidden">
      <TravelOceanScene progress={progress} />

      <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
        <div className="max-w-lg w-full px-6 pointer-events-auto">
          <div className="text-center mb-6">
            <h1 className="font-display text-3xl font-bold text-age-gold mb-1 tracking-wide drop-shadow-lg">
              {'🚢'} 항해 중...
            </h1>
            <p className="text-age-paper/90 drop-shadow text-sm">
              <span className="text-age-amber">{from?.name}</span> {from?.capital} {'→'} <span className="text-age-amber">{to?.name}</span> {to?.capital}
            </p>
          </div>

          <div className="mb-3">
            <div className="flex justify-between text-[11px] text-age-paper/80 mb-1">
              <span>{from?.capital}</span>
              <span>{to?.capital}</span>
            </div>
            <div className="w-full h-4 bg-age-navy/80 rounded-full overflow-hidden border border-age-gold/40 shadow-panel">
              <div
                className="h-full transition-all duration-500"
                style={{
                  width: `${progress}%`,
                  background: 'linear-gradient(90deg, #2eb5e0, #d4a24c)',
                }}
              />
            </div>
            <div className="flex justify-between text-[11px] text-age-paper/70 mt-1">
              <span>{progress.toFixed(0)}%</span>
              <span>{minutes}:{seconds.toString().padStart(2, '0')}</span>
            </div>
          </div>

          <div className="panel-parchment rounded-md p-3 mb-4 text-sm">
            <div className="flex justify-between text-age-paper/90 mb-1">
              <span>{'🍞'} 식량: <span className="text-age-leaf">{Math.floor(player.food)}</span></span>
              <span>{'❤️'} HP: <span className="text-age-blood">{Math.floor(player.hp)}/{player.maxHp}</span></span>
            </div>
            {totalEncounters > 0 && (
              <div className="text-age-gold text-xs mt-1">
                {'⚠️'} 이벤트: {encountersDone}/{totalEncounters}
              </div>
            )}
          </div>

          <Button variant="danger" fullWidth onClick={onCancel}>
            {'❌'} 항해 취소 (출발지로 복귀)
          </Button>
        </div>
      </div>
    </div>
  );
}
