import { useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import * as THREE from 'three';

interface TravelOceanSceneProps {
  progress: number; // 0-100
}

function Ocean() {
  const meshRef = useRef<THREE.Mesh>(null);

  useFrame(({ clock }) => {
    const mesh = meshRef.current;
    if (!mesh) return;
    const pos = mesh.geometry.attributes.position;
    const t = clock.elapsedTime;

    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i);
      const y = pos.getY(i);
      pos.setZ(i,
        Math.sin(t * 0.8 + x * 0.3) * 0.5 +
        Math.cos(t * 0.6 + y * 0.4) * 0.3 +
        Math.sin(t * 1.2 + x * 0.1 + y * 0.2) * 0.2
      );
    }
    pos.needsUpdate = true;
    mesh.geometry.computeVertexNormals();
  });

  return (
    <mesh ref={meshRef} rotation={[-Math.PI / 2, 0, 0]} position={[0, -1, 0]}>
      <planeGeometry args={[200, 100, 64, 64]} />
      <meshStandardMaterial
        color="#0a4a8a"
        roughness={0.3}
        metalness={0.1}
        transparent
        opacity={0.9}
      />
    </mesh>
  );
}

function Ship({ progress }: { progress: number }) {
  const groupRef = useRef<THREE.Group>(null);

  useFrame(({ clock }) => {
    if (!groupRef.current) return;
    const t = clock.elapsedTime;
    // Rock on waves
    groupRef.current.rotation.z = Math.sin(t * 1.5) * 0.08;
    groupRef.current.rotation.x = Math.sin(t * 1.2) * 0.05;
    groupRef.current.position.y = Math.sin(t * 0.8) * 0.3;
  });

  // Map progress (0-100) to x position (-80 to 80)
  const xPos = -80 + (progress / 100) * 160;

  return (
    <group position={[xPos, 1, 0]}>
      <group ref={groupRef}>
        {/* Hull */}
        <mesh position={[0, 0, 0]}>
          <boxGeometry args={[6, 1.5, 2.5]} />
          <meshStandardMaterial color="#8B4513" roughness={0.7} />
        </mesh>
        {/* Hull bottom (pointed) */}
        <mesh position={[0, -0.5, 0]} rotation={[0, 0, Math.PI / 4]}>
          <boxGeometry args={[1.2, 1.2, 2.3]} />
          <meshStandardMaterial color="#654321" roughness={0.7} />
        </mesh>
        {/* Mast */}
        <mesh position={[0, 3, 0]}>
          <cylinderGeometry args={[0.1, 0.12, 5, 6]} />
          <meshStandardMaterial color="#DEB887" roughness={0.8} />
        </mesh>
        {/* Sail */}
        <mesh position={[0, 3.5, 0.3]}>
          <planeGeometry args={[3, 3.5]} />
          <meshStandardMaterial color="#F5F5DC" roughness={0.9} side={THREE.DoubleSide} />
        </mesh>
        {/* Second smaller sail */}
        <mesh position={[-2, 2.5, 0.2]}>
          <planeGeometry args={[1.5, 2]} />
          <meshStandardMaterial color="#F5F5DC" roughness={0.9} side={THREE.DoubleSide} />
        </mesh>
        {/* Flag */}
        <mesh position={[0, 5.8, 0]}>
          <planeGeometry args={[1, 0.5]} />
          <meshStandardMaterial color="#e74c3c" side={THREE.DoubleSide} />
        </mesh>
      </group>
    </group>
  );
}

export default function TravelOceanScene({ progress }: TravelOceanSceneProps) {
  return (
    <Canvas
      camera={{ position: [0, 15, 30], fov: 45 }}
      gl={{ antialias: true, alpha: false }}
      style={{ position: 'absolute', inset: 0, zIndex: 0 }}
    >
      <color attach="background" args={['#0a1628']} />
      <ambientLight intensity={0.4} />
      <directionalLight position={[20, 30, 10]} intensity={0.7} />
      <directionalLight position={[-10, 20, -5]} intensity={0.3} color="#4488ff" />
      {/* Fog for atmosphere */}
      <fog attach="fog" args={['#0a1628', 40, 120]} />

      <Ocean />
      <Ship progress={progress} />
    </Canvas>
  );
}
